/* Ayan World: separate learner space, explicit adult curation, local progress. */
(()=>{
 'use strict';
 const W=window.AyanWorld,key='ayan.experience.v2',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let data;try{data=W.clean(JSON.parse(localStorage.getItem(key)));}catch{data=W.clean();}
 let tab=(()=>{try{return sessionStorage.getItem('ayan.child.tab')||'day';}catch{return 'day';}})(),lang=document.documentElement.lang==='kk'?1:0,role=window.AyanAccount?.role||'teacher',filter='all',actor=null,game=null,selection=null,order=[],round=0,matched=[],feedback='',paused=false,done=false;
 let pending;try{pending=W.cleanSession(JSON.parse(localStorage.getItem('ayan.session.v2')));}catch{pending=null;}
 const root=document.createElement('div');root.id='world';document.body.append(root);
 const tx=(a,b)=>lang?b:a;
 const paths={pairs:'M9 9h14v18H9z M25 17h14v18H25z',sequence:'M7 12h8v8H7z M20 20h8v8h-8z M33 28h8v8h-8z M15 16h9m0 0-3-3m3 3-3 3',sort:'M6 26h16v13H6z M27 26h16v13H27z M10 10h9v9h-9z M30 10h9v9h-9z',pack:'M12 17h24v25H12z M18 17v-6a6 6 0 0 1 12 0v6 M18 28h12v8H18z',pattern:'M8 16h10v10H8z M24 16l6 10 6-10z M39 21h3',puzzle:'M10 10h12q0-8 6-5t0 10h10v23H10z',listen:'M10 28v-5a14 14 0 0 1 28 0v5 M9 26h7v13H9z M32 26h7v13h-7z',route:'M12 39c30 0-12-28 20-28 M29 8l8 2-6 7 M8 38a4 4 0 1 0 8 0a4 4 0 1 0-8 0',garden:'M24 40V23 M24 31c-12 0-13-11-13-11 12 0 13 11 13 11 M24 28c12 0 13-11 13-11-12 0-13 11-13 11 M20 13a5 5 0 1 0 10 0a5 5 0 1 0-10 0',home:'M7 23 24 8l17 15 M12 20v21h24V20 M21 41V29h8v12',sun:'M24 13a11 11 0 1 0 0 22a11 11 0 1 0 0-22 M24 3v5m0 32v5M3 24h5m32 0h5M8 8l4 4m24 24 4 4M8 40l4-4m24-24 4-4'};
 function icon(n){return '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[n]||paths.garden)+'"/></svg>';}
 const mode=()=>{const kk=role==='teacher'?document.documentElement.lang==='kk':!!lang;return '<a class="world-secondary" href="/" style="font-size:14px">← '+(kk?'Платформа туралы':'О платформе')+'</a><button class="world-secondary" data-logout>'+(kk?'Шығу':'Выйти')+'</button>';};
 function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{feedback=tx('Игра работает без сохранения на этом устройстве','Бұл құрылғыда ойын сақталмайды');}}
 function stopActor(){actor?.destroy();actor=null;}
 function mascot(){stopActor();const el=root.querySelector('[data-actor]');if(el)actor=AyanMascot.create(el,{motion:data.motion});}
 function switchRole(next){if(game){closeGame();}role=next;document.body.dataset.mode=role;filter='all';render();if(role==='child')root.querySelector('h1')?.focus();}
 function setFeedback(text,clip='Encourage'){feedback=text;actor?.play(clip);const f=root.querySelector('#world-feedback');if(f)f.textContent=text;}
 function tabs(){return role!=='child'?'':'<nav class="child-tabs" aria-label="'+tx('Разделы','Бөлімдер')+'">'+[['day','Мой день','Менің күнім'],['games','Игры','Ойындар'],['video','Видео','Бейне']].map(x=>'<button data-tab="'+x[0]+'" '+(!game&&tab===x[0]?'aria-current="page"':'')+'>'+x[lang+1]+'</button>').join('')+'</nav>';}
 function header(){return '<header class="world-header"><button class="world-brand" data-home><span class="brand-leaf">'+icon('garden')+'</span>ayan<span>.</span></button>'+mode()+tabs()+'<div class="world-tools"><button data-support aria-haspopup="dialog">'+tx('Настройки','Баптаулар')+'</button><button data-lang-toggle aria-label="'+tx('Сменить язык','Тілді өзгерту')+'">'+(lang?'ҚАЗ':'РУС')+'</button><button data-motion aria-pressed="'+data.motion+'">'+icon('sun')+'<span>'+tx('Движение','Қозғалыс')+'</span></button></div></header>';}
 function preview(id){return '<div class="game-art task-preview preview-'+id+'" aria-hidden="true"><img class="game-illustration" src="assets/games/'+id+'.svg" alt="" width="128" height="128" loading="lazy"></div>';}  function cards(){return W.games.filter(g=>filter==='all'||filter==='creative'&&['garden','puzzle'].includes(g.id)||filter==='learn'&&!['garden','puzzle'].includes(g.id)).map(g=>'<button class="world-card" data-play="'+g.id+'">'+preview(g.id)+'<div class="world-card-copy"><span class="eyebrow">'+g.tag[lang]+(data.completed.includes(g.id)?' ✓':'')+'</span><h3>'+g.title[lang]+'</h3><p>'+g.desc[lang]+'</p><span class="card-arrow" aria-hidden="true">→</span></div></button>').join('');}
 function dayView(){return '<section class="day-hero"><span class="eyebrow">'+tx('Мой день','Менің күнім')+'</span><h1 tabindex="-1" id="day-title">'+tx('Сегодня','Бүгін')+'</h1><p>'+tx('Один понятный шаг за раз. Можно не спешить.','Бір уақытта бір түсінікті қадам. Асықпа.')+'</p></section><div class="day-layout"><div id="day-lesson" class="day-lesson-slot"><div class="day-card is-loading" role="status">'+tx('Загружаем урок…','Сабақты жүктеп жатырмыз…')+'</div></div><aside class="day-friend" aria-hidden="true"><div class="hero-character" data-actor></div></aside></div><nav class="day-links" aria-label="'+tx('Ещё','Тағы')+'"><button class="world-secondary" data-tab="games">'+tx('Игры','Ойындар')+' →</button><button class="world-secondary" data-tab="video">'+tx('Видео','Бейне')+' →</button></nav>';}
 function gamesView(){return '<section class="world-section" id="world-games"><div class="section-top"><div><span class="eyebrow">'+tx('Выбирай, что интересно','Қызықтысын таңда')+'</span><h2 tabindex="-1">'+tx('Во что поиграем?','Қандай ойын ойнаймыз?')+'</h2></div><div class="world-filters">'+[['all','Все игры','Барлығы'],['learn','Узнавать','Үйрену'],['creative','Создавать','Жасау']].map(x=>'<button data-filter="'+x[0]+'" aria-pressed="'+(filter===x[0])+'">'+x[lang+1]+'</button>').join('')+'</div></div><div class="world-grid">'+cards()+'</div></section><section class="garden-promo"><div class="garden-mini">'+icon('garden')+'</div><div><span class="eyebrow">'+tx('Твой сад','Сенің бағың')+'</span><h2>'+tx('Маленький сад больших стараний','Талпынысыңның шағын бағы')+'</h2><p>'+tx('За открытия появляются новые цветы. Они останутся с тобой.','Жаңа жетістіктер үшін жаңа гүлдер. Олар сенімен қалады.')+'</p></div><button class="world-secondary" data-play="garden">'+tx('В мой сад','Менің бағыма')+' ↗</button></section>';}
 function videoView(){return '<section class="video-tab" id="video-tab"><span class="eyebrow">'+tx('Видео','Бейне')+'</span><h1 tabindex="-1">'+tx('Видео со светлячком','Жарқырауық қоңызбен бейне')+'</h1><div id="video-library"></div></section>';}
 function home(){const view=role!=='child'||tab==='games'?gamesView():tab==='video'?videoView():dayView();return header()+'<main class="world-main tab-'+tab+'">'+view+'<footer class="world-footer">'+tx('Каждый шаг важен. Даже самый маленький.','Әр қадам маңызды. Ең кішкентайы да.')+'<span>ayan - '+tx('играем и учимся','ойнап үйренеміз')+'</span></footer></main>';}
 function render(){stopActor();document.body.dataset.mode=role;document.body.dataset.motion=data.motion?'on':'off';
   document.querySelectorAll('.teacher-mode-slot').forEach(e=>e.innerHTML=mode());
   if(role==='child'){root.hidden=false;root.innerHTML=game?gameShell():home();mascot();if(game)drawGame();else if(tab==='video')window.AyanVideoLibrary?.mount(root.querySelector('#video-library'),{lang:lang?'kk':'ru'});}
   else{root.hidden=true;root.innerHTML='';decorateTeacher();}
 }
 function decorateTeacher(){
   let slot=document.querySelector('.teacher-mode-slot');if(!slot){slot=document.createElement('div');slot.className='teacher-mode-slot';document.querySelector('.topbar').prepend(slot);}slot.innerHTML=mode();
   document.documentElement.dataset.theme='light';document.querySelector('#themeBtn').hidden=true;
   const app=document.querySelector('#app');
   if(document.querySelector('#nav [aria-current="page"]')?.dataset.v==='games'&&!app.querySelector('.teacher-world-catalog')){
     app.innerHTML='<section class="teacher-world-catalog"><div class="head"><div><span class="eyebrow">'+tx('Подготовка игр','Ойындарды дайындау')+'</span><h1>'+tx('Игровая библиотека','Ойын кітапханасы')+'</h1><p>'+tx('Девять способов исследовать мир. Выберите, что появится на экране ребёнка.','Әлемді танудың тоғыз жолы. Бала экранына ойындарды таңдаңыз.')+'</p></div><button class="world-primary" data-config>'+tx('Выбрать игры','Ойындарды таңдау')+' →</button></div><div class="world-grid">'+W.games.map(g=>'<button class="world-card '+g.color+'" data-config><div class="game-art"><div class="art-disc">'+icon(g.icon)+'</div></div><div class="world-card-copy"><span class="eyebrow">'+(data.enabled.includes(g.id)?tx('Доступно ребёнку','Балаға қолжетімді'):tx('Не выбрано','Таңдалмаған'))+'</span><h3>'+g.title[lang]+'</h3><p>'+g.desc[lang]+'</p></div></button>').join('')+'</div></section>';
   }
   // Home: no marketing block inside the cabinet. One quiet task card links to the games setup.
   const tasks=app.querySelector('.tasks');
   if(tasks&&!tasks.querySelector('.task-games')){const b=document.createElement('button');b.className='task task-games';b.dataset.config='';const go=tasks.querySelector('.task-go')?.innerHTML||'';b.innerHTML='<span class="task-icon">'+icon('garden')+'</span><span class="task-text"><b>'+tx('Игры и сад для ребёнка','Балаға арналған ойындар мен бақ')+'</b><span>'+tx('Выберите, какие из 9 игр появятся на экране ребёнка.','Бала экранында 9 ойынның қайсысы шығатынын таңдаңыз.')+'</span><em>'+data.enabled.length+' / 9</em></span><span class="task-go">'+go+'</span>';tasks.append(b);}
 }
 function configure(){
   const dialog=document.createElement('dialog');dialog.className='world-config';dialog.innerHTML='<form method="dialog"><span class="eyebrow">'+tx('НАСТРОЙКА ВЗРОСЛЫМ','ЕРЕСЕКТІҢ БАПТАУЫ')+'</span><h2>'+tx('Мир ребёнка начинается здесь','Баланың әлемі осы жерден басталады')+'</h2><p>'+tx('Выберите демонстрационные игры для детского режима. Перед занятием просмотрите содержание. Переключение режимов не является защитой доступа.','Бала режиміне ойындарды таңдаңыз. Сабақ алдында мазмұнын тексеріңіз.')+'</p><div class="config-list">'+W.games.map(g=>'<label><input type="checkbox" name="game" value="'+g.id+'" '+(data.enabled.includes(g.id)?'checked':'')+'><span>'+icon(g.icon)+'</span><b>'+g.title[lang]+'</b><small>'+g.tag[lang]+'</small></label>').join('')+'</div><details class="content-preview"><summary>'+tx('Посмотреть задания перед запуском','Іске қоспас бұрын тапсырмаларды қарау')+'</summary><p>'+tx('Пары: 2 + 3 → 5, 4 − 2 → 2, 3 + 3 → 6. Порядок: подготовить карандаши → нарисовать домик → раскрасить → убрать. Сортировка: 12, 67, 50, 84 по границе 50. Рюкзак: карандаши, альбом и ластик среди шести предметов. Узор: четыре ряда из кругов, ромбов и треугольников. Пазл: четыре части домика с номерами. Слова: цветок, дом, солнце. Тропинка: сложение 2 + 3, следующее после 4, число меньше 3. Сад: выбор растения и места.','Жұптар: 2 + 3 → 5, 4 − 2 → 2, 3 + 3 → 6. Рет: қарындаш дайындау, үй салу, бояу, жинау. Топтау: 12, 67, 50, 84; шекара 50. Сөмке: қарындаш, альбом, өшіргіш. Өрнек: төрт қатар. Пазл: үйдің төрт бөлігі. Сөздер: гүл, үй, күн. Жол: 2 + 3, 4 тен кейінгі сан, 3 тен кіші сан. Бақ: гүл мен орын таңдау.')+'</p></details><p class="config-note">'+tx('Демо-наборы требуют проверки педагогом. Результаты игр не являются диагностикой. Прогресс хранится только в этом браузере и пока не входит в резервную копию кабинета.','Тапсырмаларды сабаққа дейін тексеріңіз. Прогресс оқушы профилінде сақталады.')+'</p><div class="config-actions"><button type="button" class="world-secondary" data-preview>'+tx('Выбрать все','Барлығын таңдау')+'</button><button class="world-secondary" value="cancel">'+tx('Отмена','Бас тарту')+'</button><button class="world-primary" type="button" data-approve>'+tx('Сохранить выбор','Таңдауды сақтау')+' →</button></div></form>';
   document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());
   dialog.querySelector('[data-preview]').onclick=()=>dialog.querySelectorAll('input').forEach(i=>i.checked=true);
   dialog.querySelector('[data-approve]').onclick=()=>{data.enabled=[...dialog.querySelectorAll('input:checked')].map(i=>i.value);save();dialog.close();alert(tx('Выбор сохранён. Ссылку для ребёнка можно создать в разделе «Вход ребёнка».','Таңдау сақталды. Балаға кіру сілтемесін жасаңыз.'));};
 }
 function begin(id){if(!data.enabled.includes(id)){const message=tx('Эту игру сначала выбирает взрослый. Откройте кабинет учителя и нажмите «Подготовить игры».','Бұл ойынды алдымен ересек таңдауы керек.');const d=document.createElement('dialog');d.className='world-config compact';d.innerHTML='<h2>'+tx('Подготовим игру вместе','Ойынды бірге дайындайық')+'</h2><p>'+message+'</p><form method="dialog"><button class="world-primary">'+tx('Понятно','Түсінікті')+'</button></form>';document.body.append(d);d.showModal();d.onclose=()=>d.remove();return;}
   game=id;round=0;selection=null;order=id==='puzzle'?[2,0,3,1]:[];matched=[];done=false;paused=false;feedback='';
   if(pending?.game===id){round=pending.round;order=pending.order.slice();matched=pending.matched.slice();feedback=tx('Продолжаем с того места, где остановились.','Тоқтаған жерден жалғастырамыз.');}
   render();root.querySelector('#game-title')?.focus();
 }
 function setTab(next){tab=['day','games','video'].includes(next)?next:'day';try{sessionStorage.setItem('ayan.child.tab',tab);}catch{}render();root.querySelector('main h1, main h2[tabindex]')?.focus({preventScroll:false});window.dispatchEvent(new CustomEvent('ayan:tab',{detail:{tab}}));}
 function closeGameSilently(){window.speechSynthesis?.cancel();game=null;paused=false;}
 function closeGame(){window.speechSynthesis?.cancel();game=null;paused=false;render();}
 function gameShell(){const g=W.games.find(x=>x.id===game);return header()+'<main class="play-world"><div class="play-header"><button class="world-secondary" data-home>← '+tx('Все игры','Барлық ойын')+'</button><span class="eyebrow">'+g.tag[lang]+'</span><button class="world-secondary" data-pause>'+tx('Перерыв','Үзіліс')+'</button></div><div class="play-layout"><aside class="play-friend"><div data-actor></div><div class="friend-note">'+tx('Я рядом.<br>Можно не спешить.','Мен жаныңдамын.<br>Асықпа.')+'</div></aside><section class="play-panel"><div class="round-track" id="round-track"></div><h1 id="game-title" tabindex="-1">'+g.title[lang]+'</h1><p class="play-instruction" id="play-instruction"></p><div id="play-board"></div><p id="world-feedback" role="status" aria-live="polite"></p><div class="play-bottom"><button class="world-secondary" data-hint>'+icon('sun')+' '+tx('Подсказка','Кеңес')+'</button><span>'+tx('Ты можешь попробовать ещё раз','Тағы да байқап көре аласың')+'</span></div></section></div></main>';}
 function finish(){done=true;data=W.award(data,game);save();drawGame();actor?.play('Celebrate');}
 function drawGame(){const board=root.querySelector('#play-board'),instruction=root.querySelector('#play-instruction');if(!board)return;
   root.querySelector('#world-feedback').textContent=feedback;root.querySelector('#round-track').innerHTML=Array.from({length:(game==='route'||game==='pairs')?3:4},(_,i)=>'<i class="'+(done||i<round?'filled':'')+'"></i>').join('');
   root.querySelector('.play-bottom').hidden=done||paused||game==='garden';
   if(paused){instruction.textContent='';board.innerHTML='<div class="play-rest">'+icon('garden')+'<h2>'+tx('Отдохнём немного','Біраз демалайық')+'</h2><p>'+tx('Игра подождёт. Продолжим, когда захочешь.','Дайын болғанда жалғастырамыз.')+'</p><button class="world-primary" data-resume>'+tx('Я готов продолжить','Жалғастыруға дайынмын')+'</button></div>';return;}
   if(done){instruction.textContent='';board.innerHTML='<div class="play-rest completion"><div class="success-flower">'+icon('garden')+'</div><span class="eyebrow">'+tx('Задание завершено','Тапсырма аяқталды')+'</span><h2>'+tx('У тебя получилось','Қолыңнан келді')+'</h2><p>'+tx('Ты справился с заданием.<br>В твоём саду доступен новый цветок.','Тапсырманы орындадың.<br>Бағыңда жаңа гүл бар.')+'</p><button class="world-primary" data-play="garden">'+tx('В мой сад','Менің бағыма')+' →</button><button class="text-button" data-home>'+tx('Выбрать другую игру','Басқа ойынды таңдау')+'</button></div>';return;}
   if(game==='pairs'){instruction.textContent=tx('Выбери пример, затем его ответ.','Мысалды, содан кейін жауабын таңда.');const left=['2 + 3','4 − 2','3 + 3'],right=['6','5','2'];board.innerHTML='<div class="pair-board"><div>'+left.map((v,i)=>'<button data-pair-left="'+i+'" class="answer-tile '+(selection===i?'selected':'')+'" '+(matched.includes(i)?'disabled':'')+'>'+v+(matched.includes(i)?' ✓':'')+'</button>').join('')+'</div><span class="pair-connector">↔</span><div>'+right.map((v,i)=>'<button data-pair-right="'+i+'" class="answer-tile" '+(matched.includes([2,0,1][i])?'disabled':'')+'>'+v+'</button>').join('')+'</div></div>';}
   else if(game==='sequence'){instruction.textContent=tx('Выбери шаги по порядку. Первым - подготовка.','Қадамдарды ретімен таңда. Алдымен дайындал.');board.innerHTML='<div class="sequence-slots">'+Array.from({length:4},(_,i)=>'<div class="sequence-slot">'+(order[i]!==undefined?'<b>'+(i+1)+'</b>'+W.seq[order[i]][lang]:'<b>'+(i+1)+'</b><span>…</span>')+'</div>').join('')+'</div><div class="sequence-bank">'+[2,0,3,1].map(i=>[i,W.seq[i]]).map(([i,v])=>'<button class="answer-tile" data-step="'+i+'" '+(order.includes(i)?'disabled':'')+'>'+v[lang]+'</button>').join('')+'</div><div class="play-actions"><button class="world-secondary" data-undo>'+tx('Назад на шаг','Бір қадам артқа')+'</button><button class="world-primary" data-check>'+tx('Проверить','Тексеру')+'</button></div>';}
   else if(game==='sort'){const items=['12','67','50','84'];instruction.textContent=tx('Выбери число, затем подходящую корзинку.','Санды, содан кейін себетін таңда.');board.innerHTML='<div class="answer-row">'+items.map((v,i)=>'<button class="answer-tile '+(selection===i?'selected':'')+'" data-sort="'+i+'" '+(matched.includes(i)?'disabled':'')+'>'+v+(matched.includes(i)?' ✓':'')+'</button>').join('')+'</div><div class="basket-row"><button data-basket="0">'+icon('sort')+'<b>'+tx('До 50 включительно','50 ге дейін қоса')+'</b></button><button data-basket="1">'+icon('sort')+'<b>'+tx('Больше 50','50 ден көп')+'</b></button></div>';}
   else if(game==='pack'){instruction.textContent=tx('Идём рисовать. Выбери три нужные вещи.','Сурет саламыз. Үш қажетті затты таңда.');const items=[['Карандаши','Қарындаштар','pattern'],['Альбом','Альбом','puzzle'],['Мяч','Доп','sun'],['Ластик','Өшіргіш','pairs'],['Ложка','Қасық','sort'],['Подушка','Жастық','home']];board.innerHTML='<div class="object-grid">'+items.map((v,i)=>'<button class="object-tile '+(order.includes(i)?'selected':'')+'" data-pack="'+i+'" aria-pressed="'+order.includes(i)+'">'+icon(v[2])+'<span>'+v[lang]+'</span></button>').join('')+'</div><button class="world-primary" data-check>'+tx('Рюкзак готов','Сөмке дайын')+' →</button>';}
   else if(game==='puzzle'){instruction.textContent=tx('Выбери два кусочка, чтобы поменять их местами.','Орнын ауыстыру үшін екі бөлікті таңда.');board.innerHTML='<div class="puzzle-board">'+order.map((n,i)=>'<button class="puzzle-tile '+(selection===i?'selected':'')+'" style="background-position:'+(n%2*100)+'% '+Math.floor(n/2)*100+'%" data-puzzle="'+i+'" aria-label="'+tx('Часть','Бөлік')+' '+(n+1)+'"><span>'+(n+1)+'</span></button>').join('')+'</div><p class="puzzle-note">'+tx('Собери домик: 1 2 / 3 4','Үйді құрастыр: 1 2 / 3 4')+'</p>';}
   else if(game==='garden'){instruction.textContent=tx('Выбери растение, затем свободное место в саду.','Өсімдікті таңдап, бақтағы бос орынға отырғыз.');const available=Math.min(6,2+data.completed.length);board.innerHTML='<div class="garden-land">'+Array.from({length:12},(_,i)=>'<button data-plant="'+i+'" class="garden-plot '+(data.garden[i]!=null?'planted':'')+'" aria-label="'+tx('Место','Орын')+' '+(i+1)+'">'+(data.garden[i]!=null?flower(data.garden[i]):'<span>+</span>')+'</button>').join('')+'</div><div class="plant-picker">'+Array.from({length:available},(_,i)=>'<button data-flower="'+i+'" class="'+(selection===i?'selected':'')+'" aria-label="'+tx('Цветок','Гүл')+' '+(i+1)+'">'+flower(i)+'</button>').join('')+'</div><p class="garden-note">'+tx('Цветы остаются с тобой. Открой новые, проходя игры.','Гүлдер сенімен қалады. Ойындарда жаңасын аш.')+'</p>';}
   else{const q=W.question(game,round);instruction.textContent=game==='pattern'?tx('Какой фигуры не хватает в конце?','Соңында қай пішін жетіспейді?'):game==='listen'?tx('Послушай слово. Текст тоже поможет.','Сөзді тыңда. Мәтін де көмектеседі.'):q.prompt[lang];board.innerHTML=(game==='pattern'?'<div class="pattern-line">'+q.prompt.map((x,i)=>'<span class="shape shape-'+(i%3)+'">'+x+'</span>').join('')+'<span class="shape missing">?</span></div>':game==='listen'?'<button class="listen-word" data-speak>'+icon('listen')+'<b>'+q.target[lang]+'</b><span>'+tx('Нажми чтобы послушать','Тыңдау үшін бас')+'</span></button>':'<div class="route-map">'+[0,1,2].map(i=>'<span class="'+(i<=round?'on':'')+'">'+(i<round?'✓':i+1)+'</span>').join('<i></i>')+'</div>')+'<div class="answer-row">'+q.choices.map((v,i)=>'<button class="answer-tile choice" data-choice="'+i+'">'+(game==='listen'?icon(v):esc(v))+(game==='listen'?'<small>'+[['Цветок','Гүл'],['Дом','Үй'],['Солнце','Күн']][i][lang]+'</small>':'')+'</button>').join('')+'</div>';}
 }
 function flower(n){return '<svg viewBox="0 0 60 80" aria-hidden="true"><path d="M30 72V34M30 60Q8 56 13 45Q27 44 30 60M30 53Q49 48 48 39Q34 39 30 53" fill="#75a763" stroke="#548246" stroke-width="2"/><g fill="'+['#f4b1b4','#e4d681','#b7a7db','#efa97a','#c5e0a8','#9acfd4'][n%6]+'">'+[0,60,120,180,240,300].map(a=>'<ellipse cx="30" cy="22" rx="9" ry="13" transform="rotate('+a+' 30 32)"/>').join('')+'</g><circle cx="30" cy="32" r="7" fill="#fff2b3"/></svg>';}
 function correct(){setFeedback(tx('Верно, продолжим','Дұрыс, жалғастырайық'),'Wave');}
 function click(e){const b=e.target.closest('button');if(!b)return;
   if(b.hasAttribute('data-logout')){if(window.AyanAccount?.demo){location.assign('/');return;}fetch(role==='teacher'?'/api/auth/sign-out':'/api/child/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(()=>location.assign('/'));return;}
   if(b.hasAttribute('data-config'))return configure();
   if(b.dataset.tab){if(game)closeGameSilently();setTab(b.dataset.tab);return;}
   if(b.hasAttribute('data-support')){window.dispatchEvent(new CustomEvent('ayan:support-open'));return;}
   if(b.hasAttribute('data-home'))return closeGame();
   if(b.dataset.play)return begin(b.dataset.play);
   if(b.dataset.filter){filter=b.dataset.filter;render();root.querySelector('#world-games')?.scrollIntoView();return;}
   if(b.hasAttribute('data-motion')){data.motion=!data.motion;save();render();return;}
   if(b.hasAttribute('data-lang-toggle')){lang=1-lang;document.documentElement.lang=lang?'kk':'ru';render();window.dispatchEvent(new CustomEvent('ayan:lang',{detail:{lang:lang?'kk':'ru'}}));return;}
   if(b.hasAttribute('data-fly'))return actor?.play('Fly');
   if(!game||done)return;
   if(b.hasAttribute('data-pause')){window.speechSynthesis?.cancel();paused=true;drawGame();actor?.play('Rest');return;}
   if(b.hasAttribute('data-resume')){paused=false;drawGame();actor?.play('Wave');return;}
   if(paused)return;
   if(b.hasAttribute('data-hint')){const hints={pairs:['Посчитай 2 + 3: это 5.','2 + 3 = 5.'],sequence:['Сначала подготовь карандаши, затем нарисуй, раскрась и убери.','Алдымен дайында, сурет сал, боя, жина.'],sort:['50 идёт в первую корзинку.','50 бірінші себетке салынады.'],pack:['Карандаши, альбом и ластик.','Қарындаштар, альбом және өшіргіш.'],puzzle:['Сверху 1 и 2, снизу 3 и 4.','Жоғарыда 1 және 2, төменде 3 және 4.']};setFeedback(hints[game]?.[lang]||tx('Посмотри на задание ещё раз. Можно пробовать без спешки.','Тапсырманы қайта қарап көр. Асықпай байқап көр.'),'Point');return;}
   if(b.dataset.pairLeft!==undefined){selection=+b.dataset.pairLeft;feedback='';drawGame();}
   if(b.dataset.pairRight!==undefined){if(selection===null)return setFeedback(tx('Сначала выбери пример слева.','Алдымен сол жақтағы мысалды таңда.'));if([2,0,1][+b.dataset.pairRight]===selection){matched.push(selection);selection=null;round++;correct();if(matched.length===3)return finish();}else setFeedback(tx('Попробуем другую пару.','Басқа жұпты байқап көрейік.'));drawGame();}
   if(b.dataset.step!==undefined){order.push(+b.dataset.step);drawGame();}
   if(b.hasAttribute('data-undo')){order.pop();drawGame();}
   if(b.dataset.sort!==undefined){selection=+b.dataset.sort;drawGame();}
   if(b.dataset.basket!==undefined&&selection!==null){if(+b.dataset.basket===([12,67,50,84][selection]>50?1:0)){matched.push(selection);selection=null;round++;correct();if(round===4)return finish();}else setFeedback(tx('Посмотри, число больше 50?','Сан 50 ден үлкен бе?'));drawGame();}
   if(b.dataset.pack!==undefined){const n=+b.dataset.pack;order=order.includes(n)?order.filter(x=>x!==n):order.concat(n);drawGame();}
   if(b.hasAttribute('data-check')){if(W.check(game,order))return finish();setFeedback(tx('Давай проверим ещё раз. Подсказка рядом.','Тағы тексерейік. Кеңес бар.'));}
   if(b.dataset.puzzle!==undefined){const i=+b.dataset.puzzle;if(selection===null)selection=i;else{[order[selection],order[i]]=[order[i],order[selection]];selection=null;if(W.check(game,order))return finish();}drawGame();}
   if(b.dataset.choice!==undefined){const q=W.question(game,round);if(+b.dataset.choice===q.answer){round++;if(round===(game==='pattern'?4:3))return finish();correct();drawGame();}else setFeedback(tx('Попробуем ещё раз. Я рядом.','Тағы байқап көрейік. Мен жаныңдамын.'));}
   if(b.hasAttribute('data-speak')){if(!window.speechSynthesis)return setFeedback(tx('Озвучка недоступна. Выбери по слову на экране.','Дыбыс жоқ. Экрандағы сөзді оқы.'));speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(W.question(game,round).target[lang]);u.lang=lang?'kk-KZ':'ru-RU';u.rate=.8;u.onerror=()=>setFeedback(tx('Можно выбрать по слову на экране.','Экрандағы сөз арқылы таңда.'),'Idle');speechSynthesis.speak(u);}
   if(b.dataset.flower!==undefined){selection=+b.dataset.flower;drawGame();}
   if(b.dataset.plant!==undefined){if(selection===null)return setFeedback(tx('Сначала выбери цветок внизу.','Алдымен төмендегі гүлді таңда.'));data.garden[+b.dataset.plant]=selection;save();drawGame();actor?.play('Plant');}
 }
 function stash(){if(!game||game==='garden')return;pending=done?null:W.cleanSession({version:2,game,round,order,matched});try{localStorage.setItem('ayan.session.v2',JSON.stringify(pending));}catch{}}
 document.addEventListener('click',e=>{const original=e.target.closest('button');click(e);stash();if(role==='child'&&game&&e.detail===0&&original&&!original.isConnected){root.querySelector('#play-board button:not(:disabled),[data-resume],.play-header button')?.focus({preventScroll:true});}});
 window.addEventListener('ayan:render',e=>{lang=e.detail.lang==='kk'?1:0;if(role==='teacher')decorateTeacher();else document.querySelectorAll('.teacher-mode-slot').forEach(x=>x.innerHTML=mode());});
 document.addEventListener('keydown',e=>{if(role==='child'&&e.key==='Escape'&&game){if(paused){paused=false;drawGame();}else{paused=true;drawGame();actor?.play('Rest');}}});
 window.addEventListener('ayan:goto',e=>{if(role!=='child')return;if(e.detail?.game)return begin(e.detail.game);if(game)closeGameSilently();setTab(e.detail?.tab||'day');});
 window.addEventListener('ayan:profile',e=>{const p=e.detail||{};let changed=false;if(p.lang&&(p.lang==='kk'?1:0)!==lang){lang=p.lang==='kk'?1:0;document.documentElement.lang=p.lang;changed=true;}if(typeof p.motion==='boolean'&&p.motion!==data.motion){data.motion=p.motion;save();changed=true;}document.documentElement.dataset.textSize=p.textSize==='large'?'large':'normal';if(changed&&role==='child'&&!game)render();});
 render();
})();
